@CrossOrigin
@RestController
@RequestMapping("/SellerQuery")
public class SellerQueryRestController extends BaseSpringRestController {
	
	public SellerQueryRestController( SellerService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Seller using a UUID
     * @param		UUID sellerId
     * @return		Seller
     */    
    @GetMapping("/load")
    public Seller load( @RequestParam(required=true) UUID sellerId ) {
    	Seller entity = null;

    	try {  
    		entity = service.getSeller( new SellerFetchOneSummary( sellerId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Seller using Id " + sellerId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Seller business objects
     * @return		Set<Seller>
     */
    @GetMapping("/")
    public List<Seller> loadAll() {                
    	List<Seller> sellerList = null;
        
    	try {
            // load the Seller
            sellerList = service.getAllSeller();
            
            if ( sellerList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Sellers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Sellers ", exc );
        	return null;
        }

        return sellerList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Seller seller = null;
    protected SellerService service = null;
    private static final Logger LOGGER = Logger.getLogger(SellerQueryRestController.class.getName());
    
}
